function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
   if (newValue == 'excellent') {
        g_form.addInfoMessage("Thank you for your excellent feedback!");
    } else if (newValue == 'good') {
        g_form.addInfoMessage("Thank you for your good feedback!");
    } else if (newValue == 'average') {
        g_form.addInfoMessage("Thank you for your feedback, we’ll work on improving!");
    } else if (newValue == 'poor') {
        g_form.addInfoMessage("Thank you for your feedback, we'll look into the issues.");
    }

   //Type appropriate comment here, and begin script below

}
